package net.officefloor.hq.app.auditview;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's audit lines exactly as the file holds them, newest first. With a name, only the lines carrying
 *  name=&lt;the name&gt; or person=&lt;the name&gt;, compared as names are (case and surrounding spaces ignored). */
public class RespondWithAuditLines {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "name", required = false) String name, Audit audit,
            ObjectResponse<List<String>> response) {
        String wanted = name == null ? "" : name.trim();
        List<String> lines = new ArrayList<>(audit.linesOf(sheetId.trim()).stream()
                .filter(line -> wanted.isEmpty() || about(line, "name", wanted) || about(line, "person", wanted))
                .toList());
        Collections.reverse(lines);
        response.send(lines);
    }

    /** Whether the line carries key=&lt;value&gt; as a whole field, the value compared ignoring case. */
    private static boolean about(String line, String key, String value) {
        String prefix = " " + key + "=";
        for (int at = line.indexOf(prefix); at >= 0; at = line.indexOf(prefix, at + 1)) {
            int start = at + prefix.length();
            int end = start + value.length();
            if (line.regionMatches(true, start, value, 0, value.length())
                    && (end == line.length() || line.charAt(end) == ' ')) {
                return true;
            }
        }
        return false;
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Set;
import net.officefloor.hq.app.role.RoleRepository;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The records that only report figures: they never carry the steward a delegate acts for. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;

    private final ObjectProvider<RoleRepository> roles;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<RoleRepository> roles) {
        this.file = Path.of(path);
        this.roles = roles;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. A record of a change made by a user
     *  name while the sheet's today is inside a delegation of the steward role to it ends with for=&lt;the steward
     *  who delegated&gt;. */
    public void record(String entry) {
        write(entry + forDelegator(entry));
    }

    /** " for=&lt;steward&gt;" when the record's by= acts for a steward on its sheet= today, else "". */
    private String forDelegator(String entry) {
        int space = entry.indexOf(' ');
        if (space < 0 || FIGURES.contains(entry.substring(0, space))) {
            return "";
        }
        String sheet = field(entry, "sheet");
        String by = field(entry, "by");
        if (sheet == null || by == null || by.isEmpty()) {
            return "";
        }
        String delegator = roles.getObject().delegatorOf(sheet, by);
        return delegator == null ? "" : " for=" + delegator;
    }

    private static String field(String entry, String name) {
        String key = " " + name + "=";
        int start = entry.indexOf(key);
        if (start < 0) {
            return null;
        }
        start += key.length();
        int end = entry.indexOf(' ', start);
        return end < 0 ? entry.substring(start) : entry.substring(start, end);
    }

    private synchronized void write(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Every line the file holds for a sheet (carrying sheet=&lt;id&gt;), in the order they were written. */
    public synchronized java.util.List<String> linesOf(String sheetId) {
        String token = "sheet=" + sheetId;
        try {
            if (!Files.exists(file)) {
                return java.util.List.of();
            }
            return Files.readAllLines(file, StandardCharsets.UTF_8).stream()
                    .filter(line -> java.util.Arrays.asList(line.split(" ")).contains(token))
                    .toList();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records the transfer, once it is saved: on the sheet left, then its rollup lines; on the sheet arrived on, then
 *  its rollup lines. */
public class AuditPersonTransferred {
    public void audit(@Val PersonTransferred transferred, @Val Rollup before, SheetRepository sheets,
            PersonRepository people, ClaimRepository claims, RateRepository rates, PersonGradeRepository grades,
            @RequestHeader(name = "X-User", required = false) String userHeader, Audit audit) {
        String user = AuditUser.decode(userHeader);
        String from = transferred.fromSheet();
        String to = transferred.toSheet();
        audit.record("PERSON_TRANSFERRED sheet=" + from + " by=" + user + " name=" + transferred.name() + " to=" + to);
        Rollup.of(from, sheets, people, claims, rates, grades).changesSince(before, from, user)
                .forEach(audit::record);
        audit.record("PERSON_TRANSFERRED sheet=" + to + " by=" + user + " name=" + transferred.name() + " from=" + from);
        Rollup.of(to, sheets, people, claims, rates, grades).changesSince(transferred.toBefore(), to, user)
                .forEach(audit::record);
    }
}
